(function(root){'use strict';
const S=root.MT_EDUCATION_MODEL_SCHEMAS,n=(key,label,unit,value,min,max,when)=>({key,label,unit,value,min,max,when}),s=(key,label,value,options,when)=>({key,label,value,options,when});
const parts=[];for(let i=1;i<=6;i++){const group='Component '+i,shape='shape'+i,live={whenNot:{[shape]:'none'},group};parts.push({...s(shape,'Shape',i<=3?'rectangle':'none',[['none','Not used'],['rectangle','Rectangle'],['circle','Circle']]),group}, {...s('sign'+i,'Area role','solid',[['solid','Solid material'],['hole','Hole / removed material']]),...live}, {...n('x'+i,'Centre x','mm',i<=3?0:400+(i-4)*210,-2000,2000),...live}, {...n('y'+i,'Centre y','mm',i===1?140:i===3?-140:0,-2000,2000),...live}, {...n('w'+i,'Width','mm',i===2?20:i<=3?200:60,.1,2000,{[shape]:'rectangle'}),group}, {...n('h'+i,'Height','mm',i===2?260:i<=3?20:60,.1,2000,{[shape]:'rectangle'}),group}, {...n('r'+i,'Radius','mm',10,.1,1000,{[shape]:'circle'}),group});}
S.section={fn:'section',title:'Composite cross-section builder',chapter:3,description:'Build a section from up to six rectangles, circles and holes. Move components and inspect its centroid and second moments.',fields:parts,notes:['Components use centre coordinates in mm. Positive components may touch but must not overlap; holes must be nonoverlapping and entirely contained in one solid component. Boolean unions and arbitrary polygons are not represented.','Signed area and first moments locate the centroid. Ix and Iy include each local second moment plus its parallel-axis term. Ixy = Σ A(x−x̄)(y−ȳ).','The rotated-axis curve uses Iθ = (Ix+Iy)/2 + (Ix−Iy)cos(2θ)/2 − Ixy sin(2θ). A principal angle is omitted for an isotropic second-moment tensor.','Geometry only: material stiffness, connection effectiveness, local buckling and allowable stresses are separate considerations. The beam link transfers Ix, converting mm⁴ to cm⁴.']};
S['three-phase']={fn:'threePhase',title:'Three-phase supply and power factor',chapter:6,description:'Compare a balanced star or delta load, supply phase vectors and power-factor compensation.',fields:[s('connection','Balanced load connection','star',[['star','Star'],['delta','Delta']]),n('voltage','Supply line-to-line RMS voltage','V',400,1,20000),n('frequency','Supply frequency','Hz',50,1,400),n('resistance','Resistance per load phase','Ω',10,.01,10000),n('reactance','Inductive reactance per load phase','Ω',7.5,0,10000),s('bank','Capacitor-bank connection','star',[['star','Star'],['delta','Delta']]),n('capacitance','Capacitance per bank branch','µF',50,0,100000)],notes:['Balanced sinusoidal three-phase source and three identical series R+jX load branches. R is positive; X≥0 represents an inductive load. Supply and conductors are ideal.','Star: phase voltage = line voltage/√3 and line current = phase current. Delta: phase voltage = line voltage and line-current magnitude = √3 × branch current. Source line-to-neutral voltage is used for the source phasors in both cases.','P=3 Iphase² R; Q=3 Iphase² X. The shunt capacitor bank supplies Qc=3ωC Vbranch². Net Q=Q−Qc, apparent power=√(P²+Qnet²). Negative net Q indicates leading compensation.','Capacitor switching, resonance, harmonics, protection and installation design are outside this balanced steady-state model.']};
S.gears={fn:'gears',title:'Gears and mechanical power transmission',chapter:4,description:'Change teeth, speed, power and mesh losses. Compare a simple external gear train with a four-gear compound train.',fields:[s('mode','Train layout','simple',[['simple','Simple train with optional idlers'],['compound','Compound: gears 2 and 3 share a shaft']]),s('count','Number of gears','3',[['2','2'],['3','3'],['4','4']]),n('rpm','Input speed','rpm',600,1,5000),n('power','Input shaft power','kW',5,0,1000),n('efficiency','Efficiency of each external mesh','fraction',.97,.1,1),...Array.from({length:4},(_,i)=>n('teeth'+(i+1),'Gear '+(i+1)+' tooth count','teeth',[20,40,20,60][i],8,120))],notes:['External spur-gear kinematics. Tooth counts are integers. A simple train has one external mesh between adjacent gears; idlers change direction but do not compound the end-to-end tooth ratio.','In the compound layout, gears 2 and 3 share speed and shaft power; external meshes are 1–2 and 3–4. Two sign reversals give the input and output the same rotation direction.','Speed changes with the reciprocal tooth ratio. Power is reduced by the supplied efficiency at each mesh. Torque magnitude is P/|ω|. A shared shaft adds no extra loss in this model.','Pitch-circle and tooth sketches illustrate kinematics; they are not manufactured tooth profiles. Bearing loads, backlash, tooth stress and allowable power require a separate model.']};
S.psychrometrics={fn:'psychrometrics',title:'Moist air and ventilation',chapter:11,description:'Heat, cool or mix moist air and follow humidity ratio, enthalpy and condensation.',fields:[s('process','Process','heating',[['heating','Sensible heating'],['cooling','Cooling with possible condensation'],['mixing','Adiabatic mixing of two streams']]),n('pressure','Common total absolute pressure','kPa(a)',101.325,60,120),n('temperature','Initial dry-bulb temperature','°C',20,0,50),n('humidity','Initial relative humidity','%',50,.1,100),n('flow','Total dry-air mass flow','kg/s',1,.01,100),{...n('target','Final dry-bulb temperature','°C',30,0,50),whenNot:{process:'mixing'}},n('secondTemperature','Second dry-bulb temperature','°C',35,0,50,{process:'mixing'}),n('secondHumidity','Second relative humidity','%',40,.1,100,{process:'mixing'}),n('fraction','First-stream share of dry-air mass','fraction',.5,0,1,{process:'mixing'})],notes:['Ideal gas–vapour mixture at equal total pressure. Liquid-water saturation relation is limited here to 0–50 °C. A dew point below 0 °C is left uncalculated rather than extrapolated.','Humidity ratio w=0.621945 pv/(p−pv), in kg water/kg dry air. Approximate enthalpy h=1.006T+w(2501+1.86T), in kJ/kg dry air with T in °C.','Heating retains humidity ratio. Cooling retains it until saturation, then drains liquid water at the final temperature. Heat duty includes the drained condensate enthalpy 4.186T kJ/kg; negative duty means heat removal.','Mixing conserves dry-air mass, water vapour and enthalpy. Supersaturated/fog mixtures are outside this model. The state-connection line is enthalpy-linear; it is not a detailed cooling-coil path or bypass-factor model.']};
S.waves={fn:'waves',title:'Wave interference and Doppler',chapter:2,description:'Superpose travelling waves or compare source and observer signals in a stationary medium.',fields:[s('mode','Study','interference',[['interference','Interference and beats'],['doppler','One-way Doppler shift']]),n('speed','Wave speed in the medium','m/s',343,100,2000),n('frequency','Source / first-wave frequency','Hz',440,1,2000),n('secondFrequency','Second-wave frequency','Hz',442,1,2000),n('amplitude','First-wave amplitude','relative',1,0,10),n('secondAmplitude','Second-wave amplitude','relative',1,0,10),n('phase','Second-wave phase offset','°',0,-360,360),n('time','Displayed time','s',0,0,10),n('sourceVelocity','Source velocity to the right','m/s',20,-1600,1600),n('observerVelocity','Observer velocity to the right','m/s',0,-1600,1600)],notes:['One-dimensional waves propagate to the right in a stationary medium. Source and observer velocities are signed positive to the right and limited to |v|≤0.8c. No relativistic, reflected or supersonic Doppler model is included.','One-way observed frequency is fobs=fsource(c−vobserver)/(c−vsource). The forward wavelength from the moving source is (c−vsource)/fsource.','Linear superposition adds displacements. Beat frequency is |f1−f2|. The resultant-amplitude expression applies only to equal frequencies; a time-dependent envelope is otherwise visible.','Change the displayed time to move the wave profile. Interference frequencies must be within a factor 16 so that the sampled spatial chart resolves both waves.']};
S.mohr={fn:'mohr',title:'Mohr circle and plane stress',chapter:3,description:'Rotate a two-dimensional stress element and compare transformed stresses, principal stresses and the Mohr circle.',fields:[n('sx','Normal stress σx','MPa',80,-1000,1000),n('sy','Normal stress σy','MPa',20,-1000,1000),n('tau','Shear τxy','MPa',30,-1000,1000),n('angle','Counterclockwise rotation of axes','°',0,-180,180)],notes:['Symmetric plane-stress tensor [σx, τxy; τxy, σy] with tension-positive normal stress. Positive τxy acts in +y on the +x face and in +x on the +y face.','Rotated σx′=mean+(σx−σy)cos(2θ)/2+τxy sin(2θ); τx′y′=−(σx−σy)sin(2θ)/2+τxy cos(2θ). Mohr shear is plotted positive upward, so the rotated point travels by −2θ.','The radius is the maximum in-plane shear stress. It is not necessarily the three-dimensional absolute maximum shear when σz=0. No unique principal angle is shown when the circle radius is zero.','The von Mises magnitude is for plane stress. No material strength, allowable stress, fatigue or pass/fail assessment is inferred.']};
const harmonicFields=[n('frequency','Fundamental frequency','Hz',50,1,400),n('fundamental','Fundamental RMS amplitude','V',230,.001,1000),n('phase1','Fundamental phase','°',0,-180,180)];for(let i=2;i<=6;i++){harmonicFields.push({...n('order'+i,'Harmonic order','',2*i-1,2,30),group:'Harmonic '+i},{...n('amplitude'+i,'RMS amplitude','V',i===2?20:i===3?10:0,0,1000),group:'Harmonic '+i},{...n('phase'+i,'Phase','°',0,-180,180),group:'Harmonic '+i});}
S.harmonics={fn:'harmonics',title:'Harmonics and signal quality',chapter:7,description:'Build a periodic voltage from its fundamental and five harmonics, then compare its waveform and RMS spectrum.',fields:harmonicFields,notes:['Each amplitude is RMS. Integer harmonic orders must be distinct; all frequencies are exact multiples of the fundamental. Components are orthogonal over one fundamental period.','Total RMS = √Σ Vrms,n². THD relative to the nonzero fundamental = √Σn>1 Vrms,n² / Vrms,1. DC offset and interharmonics are excluded.','Peak magnitude and crest factor are sampled estimates on a 2,049-point grid; RMS and THD are calculated analytically. Phase changes can change the peak without changing RMS or THD.','This is a single periodic voltage signal, not a complete three-phase neutral-current, resonance, compliance or power-quality assessment.']};
const unitOptions=Object.values(root.MT_DISCOVERY.units).flat().map(q=>[q[0],q[1]]);
S.units={fn:'units',title:'Unit conversion workshop',chapter:1,description:'Build a conversion through the base unit, inspect the scale and offset, and try a new value.',fields:[s('group','Quantity','pressure',Object.keys(root.MT_DISCOVERY.units).map(k=>[k,k==='temperatureDifference'?'Temperature difference':k[0].toUpperCase()+k.slice(1)])),{...s('from','From','bar',unitOptions),unitChoices:true},{...s('to','To','kPa',unitOptions),unitChoices:true},n('value','Input value','',2,-1e12,1e12)],notes:['Units can be converted only inside the same physical quantity. Pressure units here are differences or consistent absolute values; gauge and absolute pressure are not interchanged automatically.','Area factors use the square of a length factor, and volume factors use its cube. Energy, power, speed and angular-speed conversions retain their separate dimensions.','The affine conversion is output = input × scale + offset. Temperature offsets apply to temperature readings; temperature differences require scale only. Values below 0 K are rejected.','One nautical mile is 1852 m. One revolution is 2π rad. One kWh is 3.6 MJ.']};
S.hydrostatics={fn:'hydrostatics',title:'Hydrostatics from hull shape',chapter:14,description:'Change a synthetic hull, draft and station count, then compare submerged volume, displacement and waterplane area.',fields:[n('length','Hull length','m',100,5,300),n('breadth','Maximum breadth at model depth','m',20,1,60),n('depth','Model depth D','m',10,1,30),n('draft','Draft T','m',5,.1,30),n('density','Water density','t/m³',1.025,.9,1.1),s('profile','Longitudinal breadth profile','parabolic',[['box','Constant breadth / box'],['parabolic','Parabolic: 4s(1−s)'],['sine','Sine: sin(πs)']]),n('flare','Vertical breadth exponent','',0,0,3),s('stations','Equally spaced stations','9',[['5','5'],['9','9'],['17','17'],['33','33'],['41','41']])],notes:['Synthetic symmetric hull with breadth b(x,z)=B f(x/L)(z/D)^a, 0≤z≤D, and no trim. This is not a vessel hydrostatic table or loading approval.','Underwater station area is B f(x/L) D (T/D)^(a+1)/(a+1). Equally spaced stations are integrated by the composite trapezoid and Simpson rules. Their difference is a comparison of methods, not a certified error bound.','Displacement mass = water density × submerged volume. Waterplane area is the integral of breadth at the selected draft. Local TPC=ρ Aw/100 in t/cm when density is in t/m³.','For this vertical power-law section, KB=T(a+1)/(a+2). TPC estimates assume a sufficiently small draft change; use reintegration when the waterplane changes appreciably.']};
S.uncertainty={fn:'uncertainty',title:'Measurement uncertainty and tolerances',chapter:1,description:'Compare first-order propagation, exact interval extrema and a reproducible distribution of sampled inputs.',fields:[s('relation','Measurement relation','product',[['product','Electrical power: P = U I'],['volume','Cylinder volume: V = π d² L / 4'],['ratio','Pressure head: H = p / (ρg)']]),n('x','First input','',10,.0001,1e6),n('y','Second input','',2,.0001,1e6),n('dx','First input ± tolerance','same unit as first',.2,0,5e5),n('dy','Second input ± tolerance','same unit as second',.1,0,5e5),n('seed','Reproducible sample seed','integer',17,1,2147483646)],notes:['The two inputs are independent uniform distributions inside the entered ± half-widths. Each half-width must be ≤50% of its positive estimate, so every sampled physical input remains positive.','Standard input uncertainty is half-width/√3. First-order combined standard uncertainty is √Σ(ci ui)² using the local sensitivity coefficients. It is an approximation for nonlinear relations.','Exact extrema are obtained from interval corners for these monotonic positive-input relations. They are tolerance bounds, not statistical confidence limits.','The histogram uses 4,096 reproducible pseudo-random samples. Empirical percentiles and sample standard deviation depend on the seed and sample size; they are not guaranteed coverage intervals. Correlation and systematic bias are excluded.']};
S.titration={fn:'titration',title:'Acid–base titration',chapter:5,description:'Add strong base to a strong or weak monoprotic acid and follow the equilibrium pH across equivalence.',fields:[s('acid','Initial acid','weak',[['weak','Weak monoprotic acid HA'],['strong','Fully dissociated monoprotic acid']]),n('acidConcentration','Initial acid concentration','mol/L',.1,.001,1),n('acidVolume','Initial acid volume','mL',25,1,1000),n('baseConcentration','Strong-base concentration','mol/L',.1,.001,1),n('baseVolume','Added base volume','mL',12.5,0,20000),n('pKa','Weak-acid pKa','',4.76,2,8,{acid:'weak'})],notes:['Ideal dilute aqueous solution at 25 °C; Kw=10⁻¹⁴ and activities are approximated by molar concentrations. Volumes are additive. Nonideal ionic-strength corrections, heat effects and polyprotic acids are excluded.','The initial acid amount and sodium amount are diluted into the total volume after each addition. Weak acid obeys Ka=[H⁺][A⁻]/[HA], and all states satisfy charge balance [H⁺]+[Na⁺]=[OH⁻]+[A⁻].','A positive hydrogen concentration is solved across the entire curve rather than switching between separate buffer and excess-base approximations. Equivalence is based on acid/base amounts, not an assumed pH of 7 for weak acid.','The selected base volume is the amount already added. Curve points include the initial state, half-equivalence and equivalence. The model does not prescribe an indicator or laboratory procedure.']};
for(const [id,keys]of Object.entries({mohr:['angle'],waves:['time','phase'],psychrometrics:['humidity'],harmonics:['phase1'],hydrostatics:['draft']}))for(const f of S[id].fields)if(keys.includes(f.key)){f.slider=true;f.sliderStep=f.key==='time'?.00001:f.key==='draft'?.01:.1;}
S.gears.fields.find(f=>f.key==='count').when={mode:'simple'};
for(const f of S.gears.fields){if(f.key==='teeth3')f.whenAny=[{mode:'compound'},{count:'3'},{count:'4'}];if(f.key==='teeth4')f.whenAny=[{mode:'compound'},{count:'4'}];}
for(const f of S.waves.fields){if(['secondFrequency','secondAmplitude','phase','time'].includes(f.key))f.when={mode:'interference'};if(['sourceVelocity','observerVelocity'].includes(f.key))f.when={mode:'doppler'};}
// Select-backed numeric controls are parsed as numbers by the model, not coerced by HTML limits.
S.gears.fields.find(f=>f.key==='count').numeric=true;S.hydrostatics.fields.find(f=>f.key==='stations').numeric=true;
})(typeof window!=='undefined'?window:globalThis);
